#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Operation (x,y): split into A=[0..x-1], B=[x..n-y-1], C=[n-y..n-1]
    // Result: C + B + A
    auto doOp = [&](int x, int y) {
        vector<int> np;
        for(int i = n - y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n - y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x, y});
    };

    for(int placed = 0; placed < n - 1; placed++) {
        int pos = -1;
        for(int i = placed; i < n; i++) {
            if(p[i] == placed + 1) { pos = i; break; }
        }
        if(pos == placed) continue;

        // Step 1: Move element from pos to position 0
        if(pos > 0 && pos < n - 1) {
            // x = pos, y = n - pos - 1; check x+y = n-1 < n. OK since pos>=1 and n-pos-1>=1
            // C = [pos+1..n-1], B = [pos..pos], A = [0..pos-1]
            // Result: C + [p[pos]] + A => p[pos] is at position n-1-pos
            // That puts it at n-1-pos, not 0. Let me think differently.

            // To move p[pos] to position 0: use x=pos+1, y=n-pos-1 if valid
            // But x+y = n, invalid.

            // Use: x = 1, y = n - pos. Then C = [pos..n-1], B = [1..pos-1], A = [0]
            // Result: [p[pos]..p[n-1], p[1]..p[pos-1], p[0]]
            // p[pos] goes to position 0. Need y=n-pos>=1 (true since pos<=n-1), x=1, x+y=n-pos+1<=n-1 => pos>=2
            if(pos >= 2) {
                doOp(1, n - pos);
            } else {
                // pos == 1: x=1, y=n-1 => x+y=n, invalid. Use x=2, y=n-2 if n>=4
                // C=[2..n-1], B=empty, A=[0,1]. Result: [p[2]..p[n-1],p[0],p[1]]. p[1] goes to n-1.
                // Then use x=1, y=1: C=[n-1], B=[1..n-2], A=[0]. p[1] (now at n-1) goes to pos 0.
                if(n >= 4) { doOp(2, n - 2); doOp(1, 1); }
                else { doOp(1, 1); } // n==3: this cycles, might need adjustment
                pos = -1;
                for(int i = placed; i < n; i++) if(p[i]==placed+1){pos=i;break;}
                if(pos == placed) continue;
                if(pos != 0 && pos >= 2) doOp(1, n - pos);
                else if(pos == 0) goto step2;
                else continue;
            }
        } else if(pos == n - 1) {
            doOp(1, 1); // brings p[n-1] to position 0
        }
        // Now element should be at position 0
        step2:
        if(p[placed] == placed + 1) continue;
        // Step 2: move from position 0 to position placed
        if(placed > 0 && placed < n - 1) {
            doOp(placed, n - placed - 1);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n", x, y);
}
